let user=null,profile=null,classroom=null,students=[],periods=[],weeklySettings=[],timetableReady=false,dayRow=null,page='dashboard',modalNode=null,boardSession=null,selectedDate=null,selectedWeekday=((new Date().getDay()+6)%7)+1,googleToken=null,googleCourses=[],googleRoster=[],googleCourseId='',boardTimer=null,boardRefresh=null,earlyPassTimer=null,currentGoal=null,boardPeriodId=null,boardPeriodManual=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
