 const roleWrap=el('div','field',''),roleLabel=el('label','','Account type'),role=document.createElement('select');role.id='signup-role';roleLabel.htmlFor=role.id;
 [['STUDENT','Student'],['TEACHER','Teacher / classroom']].forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;role.append(option)});roleWrap.append(roleLabel,role);
 const className=makeField('signup-class','Class');
